<script setup lang="ts">import {Head,Link,router} from '@inertiajs/vue3';defineProps<{payments:any}>();const verify=(p:any,decision:string)=>{const note=decision==='reject'?window.prompt('Alasan penolakan:')||'':null;if(decision==='reject'&&!note)return;router.patch(`/admin/payments/${p.id}/verify`,{decision,note},{preserveScroll:true});};</script>
<template><Head title="Pembayaran"/><main class="min-h-screen bg-slate-100 p-5"><section class="mx-auto max-w-7xl"><Link href="/admin/dashboard" class="text-emerald-700">← Dashboard</Link><h1 class="text-3xl font-bold text-emerald-950">Pembayaran</h1><div class="mt-6 overflow-x-auto rounded-2xl bg-white"><table class="w-full text-left text-sm"><thead class="bg-emerald-950 text-white"><tr><th class="p-4">Pendaftar</th><th class="p-4">Provider</th><th class="p-4">Nominal</th><th class="p-4">Status</th><th class="p-4">Aksi manual</th></tr></thead><tbody><tr v-for="p in payments.data" :key="p.id" class="border-b"><td class="p-4">{{p.applicant.registration_number}} — {{p.applicant.full_name}}</td><td class="p-4">{{p.provider}}</td><td class="p-4">Rp {{Number(p.total_amount).toLocaleString('id-ID')}}</td><td class="p-4">{{p.status}}</td><td class="p-4"><span v-if="p.provider==='manual'&&p.status==='pending'" class="flex gap-2"><button @click="verify(p,'accept')" class="rounded-lg bg-emerald-700 px-3 py-1 text-white">Terima</button><button @click="verify(p,'reject')" class="rounded-lg bg-red-100 px-3 py-1 text-red-800">Tolak</button></span></td></tr></tbody></table></div></section></main></template>
